sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    try {
        // initializing; extracting data from the request body
        var requestBody = request.body.data.HEADER,
            payload = request.body.data.PAYLOAD,
            requestData = requestBody;

        var responseBody = {};

        // Mandatory Field checks and logging of error if missing or invalid fields 

        var eventsArray = [];
        if (requestData.messageid == '' || requestData.messageid == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Message Id'));
            return;
        }
        if (requestData.eventtype == '' || requestData.eventtype == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Event Type'));
            return;
        }
        // if (requestData.source == '' || requestData.source == undefined) {
        //     response.setError(new sn_ws_err.BadRequestError('Missing Source'));
        //     return;
        // }
		if (requestData.source == '' || requestData.source == undefined || (requestData.source != 'STM-ITM' && requestData.source != 'STM-DET')) {
            response.setError(new sn_ws_err.BadRequestError('Missing / Invalid Source'));
            return;
        }
        if (requestData.objectid == '' || requestData.objectid == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Object Id'));
            return;
        }
        if (requestData.objecttype == '' || requestData.objecttype == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Object Type'));
            return;
        }
        if (requestData.objectidtype == '' || requestData.objectidtype == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Object Id Type'));
            return;
        }
        if (requestData.objectversion == '' || requestData.objectversion == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Object Version'));
            return;
        }
        if (requestData.eventstatus == '' || requestData.eventstatus == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Event Status'));
            return;
        }
        if (requestData.eventdatetime == '' || requestData.eventdatetime == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Event Date Time'));
            return;
        }


        // Processing record based on source
        if (requestData.source == 'STM-ITM' || requestData.source == 'STM-DET') {
            var grWidget = new GlideRecord('x_hsb11_mss_opti_0_mss_app_widget_inbound');
            grWidget.addQuery('message_id', requestData.messageid);
            grWidget.addQuery('source', requestData.source);
            grWidget.query();
            if (grWidget.next()) {
                response.setError(new sn_ws_err.BadRequestError('Duplicate messageid. This event has already been processed.'));
                response.setStatus(409);
                return;
            } else {
                // Insert new record in the table
                eventsArray = new x_hsb11_mss_opti_0.MSS_Optimus_Utils().insertInboundWidgetRecord(requestData, payload);
            }
            responseBody.message = 'SSVMO-ESI CASHFLOWS -  Payload processed successfully.';
            response.setBody(responseBody);
            response.setStatus(200);
        } else {
			responseBody.message = 'SSVMO-ESI CASHFLOWS - Invalid Source.';
            response.setBody(responseBody);
            response.setStatus(400);
        }

        // responseBody.message = 'SSVMO-ESI CASHFLOWS -  Payload processed successfully.';
        // response.setBody(responseBody);
        // response.setStatus(200);

    } catch (e) {
        gs.error('Scripted REST API Resource - el_inbound_event_optimus_cash_flow: Unkonwn exception while processing Optimus request' + e.message);
        response.setStatus(400);
        response.setError('Scripted REST API Resource - el_inbound_event_optimus_cash_flow: Unkonwn exception while processing Optimus request');
    }

})(request, response);
